Definition NP_A : Z := 0x11f024.
Definition NP_RET_A : Z := 0x11f0dc.
Definition BSEQ_LAST_A : Z := 26339969.
Definition RO_LO_A : Z := 0x10000.
Definition RO_HI_A : Z := 0x17e000.

Definition kn_npA : list kentry :=
  [ KRange (EVar 2) (2 ^ 24) (2 ^ 47)
  ; KAlign (EVar 2) 16
  ; KWr (SA (EVar 2) (-16)) (ELit 16)
  ; KImg RO_LO_A RO_HI_A ].

Definition sr_npA (n : Z) : list expr := sr_upd sr_id (ridx 10%bv) (ELit n).

Record np_certA (n r : Z) : Prop := NPCA {
  npca_ss  : sym_state;
  npca_scr : scripts;
  npca_run : sym_exec ASEGS 200000 true [NP_RET_A] (SCR [] [] []) (SS NP_A (sr_npA n) [] kn_npA 40) [] = (npca_ss, [], npca_scr);
  npca_a0  : sr_get (s_regs npca_ss) 10%bv = ELit r;
  npca_pc  : s_pc npca_ss = NP_RET_A;
  npca_cs  : kept_syms (s_regs npca_ss) = true;
  npca_log : s_log npca_ss = [SE (SA (EVar 2) (-8)) 8 (EVar 1)]
}.

Section NPA.
  Context {fx : FPState}.
  Variables (R : bvmap 5 word) (M : mem) (sp : Z) (ret : word).
  Hypothesis Hra : getr R 1%bv = ret.
  Hypothesis Hret : ret_ok ret.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 sp.
  Hypothesis Hsp16 : sp mod 16 = 0.
  Hypothesis Hsplo : 2 ^ 24 <= sp.
  Hypothesis Hsphi : sp <= 2 ^ 47.
  Hypothesis Hroom : stack_room ASEGS M sp 16.
  Hypothesis Hro : forall i, RO_LO_A <= i < RO_HI_A -> M (Z_to_bv 64 i) = None.

  Let E := Eseed R [].

  Lemma np_knowA : know_ok ASEGS E M kn_npA.
Proof using R M sp Hsp Hsp16 Hsplo Hsphi Hroom Hro.
