  Lemma np_oneA : forall n r,
    getr R 10%bv = Z_to_bv 64 n -> np_certA n r ->
    exists R',
      msteps ASEGS (@mkst fx R (Z_to_bv 64 NP_A) M (seg_rom ASEGS))
