Definition next_prime_stmt_A : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (bc sp : Z) (ret : word),
    In bc BSEQ -> bc <> 0 -> bc <> BSEQ_LAST_A ->
    getr R 10%bv = Z_to_bv 64 (np_arg bc) ->
    getr R 1%bv = ret -> ret_ok ret -> getr R 2%bv = Z_to_bv 64 sp ->
    sp mod 16 = 0 -> 2 ^ 24 <= sp -> sp <= 2 ^ 47 ->
    stack_room ASEGS M sp 16 -> (forall i, RO_LO_A <= i < RO_HI_A -> M (Z_to_bv 64 i) = None) ->
    exists R',
      msteps ASEGS (@mkst fx R (Z_to_bv 64 NP_A) M (seg_rom ASEGS))
                   (@mkst fx R' ret (wbytes M (Z_to_bv 64 (sp - 8)) (word_to_le_bytes 8 ret)) (seg_rom ASEGS))
      /\ kept R R'
      /\ getr R' 10%bv = Z_to_bv 64 (bseq_next bc).

